# carry it, and tools/lint_catalog_drift.py asserts the three agree.

scan_regions = input('scan_regions')
exempt       = (input('exempt_assets') || {})['CKV_AWS_148'] || []

control 'CKV_AWS_148' do
  title 'Ensure no default VPC is planned to be provisioned'

  desc <<~DESC
    Checkov asserts this against Terraform. This profile asserts it against
    the aws_default_vpc resources that actually exist, read through the
    stock inspec-aws aws_vpc resource.
  DESC

  desc 'rationale', <<~RATIONALE
    A default VPC ships with a public subnet in every availability zone, an
    internet gateway and a security group that allows all traffic between
    its members. An instance launched without an explicit subnet lands
    there.
  RATIONALE

  desc 'check', <<~CHECK
    Checkov looks for: any aws_default_vpc resource is declared at all
  CHECK

  desc 'fix', <<~'FIX'
    Terraform — aws_default_vpc:

      # There is no Terraform that removes a default VPC: `aws_default_vpc`
      # ADOPTS the existing one, and destroying that resource only drops it
      # from state. Manage the workload's own VPC instead, and delete the
      # default out of band.
      resource "aws_vpc" "app" {
        cidr_block           = "10.0.0.0/16"
        enable_dns_hostnames = true

        tags = {
          Name = "app"
        }
      }

    Out of band — aws_default_vpc:

      aws ec2 delete-vpc --vpc-id <default-vpc-id> --region <region>

    Note (aws_default_vpc): Delete the default VPC in every enabled region, not
    just the one you work in, and detach or delete its internet gateway, subnets
    and route tables first. Anything already launched into it must be moved
    before the delete will succeed.
  FIX

  tag checkov_id:            'CKV_AWS_148'
  tag checkov_category:      'NETWORKING'
  tag checkov_version:       '3.3.16'
  tag checkov_kind:          'custom'
  tag tf_resources:          %w[aws_default_vpc]
  tag tf_docs:               'https://registry.terraform.io/providers/hashicorp/aws/latest/docs/resources/default_vpc'
  tag nist:                  ['SC-7', 'CM-7']
  tag nist_r4:               ['SC-7', 'CM-7']
  tag cci:                   ['CCI-001097', 'CCI-000381']
  tag ksi:                   ['KSI-CNA-NDS']
  tag severity:              'medium'
  tag severity_source:       'assessed'
  tag nist_source:           'agent-drafted'
  tag implementation_status: 'implemented'

  # Enumerated at control scope, then each asset asserted on its own. The
  # resource is an ARGUMENT to `describe`, which evaluates on the control --
  # calling it inside the block would defer it into the example.
  #
  # Every call carries aws_region: a stock resource otherwise reads only the
  # region the connection was built with, and every other region's resources
  # report as absent, which renders Not Applicable rather than unexamined.
  found = checkov_scan_regions(scan_regions).flat_map do |region|
    aws_vpcs(aws_region: region).vpc_ids.to_a.map { |id| [id, region] }
  end

  # A plural resource whose table is built from the API response returns nil for
  # a column that does not exist, rather than raising. Passing that on gives
  # "`[:x]` must be provided" and kills the control. Blank ids are separated out
  # and asserted on below, so a wrong `ids` column is a visible failure rather
  # than a crash or a silent Not Applicable.
  unusable = found.count { |id, _r| "#{id}".strip.empty? }
  found = found.reject { |id, _r| "#{id}".strip.empty? }
  in_scope = found.reject { |id, _r| checkov_exempt?(id: id, type: 'aws_default_vpc', rules: exempt) }

  if unusable.positive?
    describe "aws_default_vpc enumeration" do
      it 'produced usable identifiers' do
        expect(unusable).to eq(0),
          "#{unusable} row(s) had a blank id — the `ids` column in resource_map.yml "          'likely names a field this resource does not expose'
      end
    end
  end

  # `unusable.positive?` keeps the control APPLICABLE when every id came back
  # blank. Without it only_if skips the control, and the wrong-column case this
  # guard exists to catch is exactly the case it would suppress — a Not
  # Applicable that means "the enumeration is broken".
  applicable = !in_scope.empty? || unusable.positive?
  impact 0.5
  impact 0.0 unless applicable
  only_if('no aws_default_vpc in scope') { applicable }

  in_scope.each do |id, region|
    describe aws_vpc(vpc_id: id, aws_region: region) do
      its('is_default') { should eq false }
    end
  end
end
